/**
 * The safety route's shipped content (src/data/content/safety.json, generated by scripts/safety/fixture.py and
 * scripts/content-snapshot/build.mjs from schema/safety-route.cypher). Mirrors the payload; the server's answer
 * vocabulary is functions/src/safety/safetyAsk.ts (SAFETY_ANSWERS) and checkRecord.ts.
 */
export type SafetyAnswer = 'no' | 'declined' | 'passing' | 'strong' | 'plan' | 'act';

export interface SafetyChoice<T extends string = string> {
  id: T;
  label: string;
  /** Shown only when every key matches the route's state (act, kind). */
  showWhen?: Record<string, string>;
}

export interface SafetyLine {
  id: string;
  name: string;
  kind: string;
  phone: string | null;
  sms: string | null;
  smsBody: string | null;
  chatUrl: string | null;
  hours: string | null;
  languages: string[];
}

export interface SafetyCountry {
  id: string;
  name: string;
  emergency: string;
  emergencyAlt: string | null;
  firearmPrompt: boolean;
  lines: SafetyLine[];
}

export interface SafetyFlow {
  version: string;
  repeat: { afterNoHours: number; afterOtherHours: number };
  answerRank: Record<SafetyAnswer, number>;
  findAHelpline: { label: string; url: string };
  people: Record<string, string>;
  header: Record<string, string>;
  question: {
    title: string;
    choices: SafetyChoice<SafetyAnswer>[];
    helpNowTitle: string;
    saidTitle: string;
    saidChoices: SafetyChoice<SafetyAnswer>[];
  };
  passing: Record<string, string>;
  declined: { line: string };
  strong: Record<string, string>;
  quickPlan: { steps: Array<{ id: string; title: string; placeholder: string }>; ownMax: number; save: string; saved: string; deviceSaved: string };
  means: {
    title: string; choices: SafetyChoice[]; actionsTitle: string; actions: SafetyChoice[]; did: string;
    calmTitle: string; medsLine: string; firearm: string;
  };
  act: {
    title: string; choices: SafetyChoice[]; kindTitle: string; kinds: SafetyChoice[];
    medicalTitle: string; medicalLine: string; tookLine: string; poison: string; medicalChoices: SafetyChoice[];
    firstAid: string; nextDay: string; nextDayChoices: SafetyChoice[];
  };
  exit: { button: string; title: string; choices: SafetyChoice[]; back: string };
  checkin: { title: string; choices: SafetyChoice[] };
  morning: { title: string; choices: SafetyChoice[]; okay: string; hard: string; twiceHard: string };
  signedOut: Record<string, string>;
  cantTell: string;
  plan: SafetyPlanCopy;
}

/** A chip in the plan builder. `toolId`: a coping chip that opens that tool; `firearm`: only where the country asks. */
export interface PlanChip { id: string; label: string; toolId?: string; firearm?: boolean }

export type PlanStepId = 'signs' | 'coping' | 'distract' | 'people' | 'pros' | 'safer' | 'reasons' | 'hear' | 'review';

/** CORE-02's copy and chip catalogues (FLOW.plan in scripts/safety/content.py). */
export interface SafetyPlanCopy {
  title: string; intro: string; flooded: string; floodedGo: string; floodedLater: string;
  next: string; skip: string; back: string; ownLabel: string; ownMax: number; fromDraft: string;
  steps: Array<{ id: PlanStepId; title: string; hint: string }>;
  signGroups: Array<{ id: string; label: string; chips: PlanChip[] }>;
  kit: { has: string; edit: string; make: string; makeSub: string; open: string };
  coping: PlanChip[];
  distract: PlanChip[];
  person: { name: string; phone: string; text: string; textDefault: string; add: string; remove: string; max: number; up: string };
  pros: { roles: PlanChip[]; add: string; max: number };
  safer: PlanChip[];
  saferOwn: string;
  reasons: PlanChip[];
  save: string; saved: string; savedDevice: string; saveFailed: string; edit: string; empty: string;
  use: { title: string; did: string; next: string; done: string; openTool: string; call: string; text: string; end: string };
  review: { title: string; line: string; keep: string; change: string };
  draftHub: string; draftHubSub: string;
}

export interface SafetyContent {
  version: string;
  flow: SafetyFlow;
  /** SafetyFlag id → its user copy (the clinician's `action` never ships). */
  flags: Record<string, string>;
  countries: SafetyCountry[];
}

/** What the check-in result carries while the route is on (functions/src/safety/safetyAsk.ts). */
export interface SafetyAsk {
  ask: boolean;
  reasons: string[];
}
